<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/employee_admin.php';require_once __DIR__.'/task_workflow.php';
$isAdmin=($taskWorkspaceRole??'employee')==='admin';$isAdmin?require_admin():require_login_any_role(['employee']);$actor=current_user()??[];$svc=new TaskWorkflowService(get_db(),$actor);$ok=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{require_valid_csrf();$a=(string)($_POST['task_action']??'');$id=(int)($_POST['task_id']??0);$v=(int)($_POST['version']??0);if($a==='create'){$initial=[];$f=$_FILES['attachments']??[];foreach((array)($f['name']??[]) as $i=>$name)if($name!=='')$initial[]=['name'=>$name,'tmp_name'=>$f['tmp_name'][$i]??'','error'=>$f['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$f['size'][$i]??0];$svc->create($_POST,$initial);$ok='Official task assigned.';}elseif($a==='post'){$svc->post($id,$v,(string)($_POST['message_type']??'reply'),trim((string)($_POST['body']??'')));$ok='Message posted.';}elseif($a==='upload'){$svc->upload($id,$v,$_FILES['attachment']??[]);$ok='Proof uploaded.';}elseif($a==='reassign'){$svc->reassign($id,$v,(int)($_POST['assignee_id']??0));$ok='Task reassigned.';}elseif($a==='revise'){$svc->revise($id,$v,($_POST['due_date']??'')?:null,($_POST['due_time']??'')?:null,(string)($_POST['priority']??'medium'));$ok='Schedule updated.';}elseif($a==='archive'){$svc->archive($id,$v,!empty($_POST['archive']));$ok='Archive updated.';}else{$svc->transition($id,$v,$a,trim((string)($_POST['body']??'')));$ok='Workflow updated.';}}catch(Throwable $e){$error=$e->getMessage();}}
function te(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$db=get_db();$where=$isAdmin?'1=1':'t.assignee_id=:uid';$p=$isAdmin?[]:[':uid'=>(int)$actor['id']];foreach(['status'=>'workflow_status','next_action'=>'responsibility','priority'=>'workflow_priority','employee'=>'assignee_id'] as $q=>$col)if(!empty($_GET[$q])&&$_GET[$q]!=='all'){$where.=" AND t.$col=:$q";$p[":$q"]=$_GET[$q];}$view=(string)($_GET['view']??'active');$where.=match($view){'completed'=>" AND t.workflow_status='completed' AND t.archived_flag=0",'cancelled'=>" AND t.workflow_status='cancelled' AND t.archived_flag=0",'archived'=>' AND t.archived_flag=1',default=>" AND t.workflow_status NOT IN ('completed','cancelled') AND t.archived_flag=0"};if(trim((string)($_GET['search']??''))!==''){$where.=' AND (t.title LIKE :search OR t.description LIKE :search OR t.category LIKE :search OR t.linked_entity_id LIKE :search)';$p[':search']='%'.trim((string)$_GET['search']).'%';}$s=$db->prepare("SELECT t.*,u.full_name assignee_name,o.occurrence_number FROM portal_tasks t LEFT JOIN users u ON u.id=t.assignee_id LEFT JOIN task_occurrences o ON o.task_id=t.id WHERE $where ORDER BY CASE t.responsibility WHEN 'admin' THEN 0 WHEN 'employee' THEN 1 ELSE 2 END,CASE t.workflow_priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,CASE WHEN t.due_date<date('now') THEN 0 WHEN t.due_date=date('now') THEN 1 ELSE 2 END,t.last_activity_at DESC");$s->execute($p);$tasks=$s->fetchAll();$employees=(new EmployeeFsStore())->listEmployees();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$isAdmin?'Task Operations':'My Work'?></title><style>body{margin:0;background:#f3f6fb;color:#172033;font:15px system-ui}.wrap{max-width:1180px;margin:auto;padding:18px}.panel,.card{background:#fff;border:1px solid #dbe3ef;border-radius:16px;padding:16px;margin-bottom:14px}.grid,.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.cards{grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}input,select,textarea,button{font:inherit;padding:10px;border:1px solid #b8c4d6;border-radius:9px;box-sizing:border-box;width:100%}textarea{min-height:75px}button{background:#174ea6;color:#fff;font-weight:700;min-height:42px}.task{border-left:5px solid #5271ff}.meta,.actions{display:flex;gap:7px;flex-wrap:wrap}.pill{padding:4px 8px;background:#eef3fb;border-radius:99px;font-size:12px}.actions form{display:flex;gap:5px;flex:1;min-width:210px}.timeline{border-left:2px solid #ccd7e8;margin:12px 5px;padding-left:12px}.entry{margin:10px 0;overflow-wrap:anywhere}.alert{padding:12px;border-radius:9px}.error{background:#fee2e2}.success{background:#dcfce7}@media(max-width:540px){.wrap{padding:9px}.cards{display:block}.task{margin-bottom:12px}.actions form{min-width:100%}}</style></head><body><main class="wrap"><header class="panel"><a href="<?=$isAdmin?'admin-dashboard.php':'employee-dashboard.php'?>">← Dashboard</a><h1><?=$isAdmin?'Task Operations':'My Work'?></h1><p><?=$isAdmin?'Official assignments and accountable review.':'Official assigned work; personal reminders are counted separately.'?></p></header><?php if($ok):?><p class="alert success"><?=te($ok)?></p><?php endif;if($error):?><p class="alert error"><?=te($error)?></p><?php endif?>
<?php if($isAdmin):?><details class="panel"><summary><b>Assign official work</b></summary><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="task_action" value="create"><div class="grid"><label>Title<input required name="title"></label><label>Employee<select required name="assignee_id"><option value="">Select</option><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>"><?=te($e['name'])?></option><?php endforeach?></select></label><label>Priority<select name="priority"><?php foreach(['low','medium','high','urgent'] as $x):?><option><?=$x?></option><?php endforeach?></select></label><label>Category<input name="category"></label><label>Start<input type="date" name="start_date"></label><label>Due<input type="date" name="due_date"></label><label>Time<input type="time" name="due_time"></label><label>Recurrence<select name="frequency_type"><?php foreach(['once','daily','weekly','monthly','custom'] as $x):?><option><?=$x?></option><?php endforeach?></select></label><label>Custom days<input type="number" min="1" name="custom_every_n_days"></label><label>Reference type<select name="linked_entity_type"><option value="">None</option><option>customer</option><option>project</option><option>site</option></select></label><label>Reference ID<input name="linked_entity_id"></label><label>Initial attachments<input type="file" name="attachments[]" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt"></label></div><label>Detailed instructions<textarea required name="description"></textarea></label><label>Expected outcome<textarea required name="expected_outcome"></textarea></label><label><input style="width:auto" type="checkbox" name="proof_required" value="1"> Require proof</label><button>Assign</button></form></details><?php endif?>
<form class="panel grid" method="get"><label>Search<input name="search" value="<?=te($_GET['search']??'')?>"></label><label>View<select name="view"><?php foreach(['active','completed','cancelled','archived'] as $x):?><option <?=$view===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></label><label>Status<select name="status"><option>all</option><?php foreach(TaskWorkflowService::STATES as $x):?><option><?=$x?></option><?php endforeach?></select></label><label>Next action<select name="next_action"><option>all</option><option>admin</option><option>employee</option><option>none</option></select></label><label>Priority<select name="priority"><option>all</option><option>urgent</option><option>high</option><option>medium</option><option>low</option></select></label><?php if($isAdmin):?><label>Employee<select name="employee"><option>all</option><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>"><?=te($e['name'])?></option><?php endforeach?></select></label><?php endif?><button>Filter</button></form>
<section class="cards"><?php foreach($tasks as $t):$d=$svc->detail((int)$t['id']);?><article class="card task" id="task-<?=$t['id']?>"><h2><?=te($t['title'])?></h2><div class="meta"><span class="pill"><?=te(str_replace('_',' ',$t['workflow_status']))?></span><span class="pill"><?=$t['responsibility']==='none'?'No action required':'Next action: '.ucfirst($t['responsibility'])?></span><span class="pill"><?=te($t['workflow_priority'])?></span><span class="pill">Occurrence <?=te($t['occurrence_number']??1)?></span></div><p><b>Assigned:</b> <?=te($t['assignee_name'])?><br><b>Due:</b> <?=te(trim((string)$t['due_date'].' '.(string)$t['due_time']))?><br><b>Category/reference:</b> <?=te(trim((string)$t['category'].' '.(string)$t['linked_entity_type'].' '.(string)$t['linked_entity_id']))?></p><p><b>Instructions</b><br><?=nl2br(te($t['description']))?></p><p><b>Expected outcome</b><br><?=nl2br(te($t['expected_outcome']))?></p><?php if($t['submission_summary']):?><p><b>Submission:</b> <?=nl2br(te($t['submission_summary']))?></p><?php endif?><details><summary>Chronological timeline</summary><div class="timeline"><?php foreach($d['messages'] as $m):?><div class="entry"><b><?=te($m['message_type'])?> · <?=te($m['actor_name'])?></b> <small><?=te($m['created_at'])?></small><br><?=nl2br(te($m['body']))?></div><?php endforeach;foreach($d['events'] as $e):?><div class="entry"><b>Activity: <?=te($e['event_type'])?></b> · <?=te($e['actor_name']??'System')?> <small><?=te($e['created_at'])?></small></div><?php endforeach;foreach($d['attachments'] as $a):?><div class="entry"><a href="task-attachment.php?id=<?=$a['id']?>"><?=te($a['original_name'])?></a> (<?=te($a['media_type'])?>)</div><?php endforeach?></div></details>
<div class="actions"><?php foreach($isAdmin?['admin_response','correction','approve','reopen','cancel']:['acknowledge','start','block','submit'] as $a):?><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="<?=$a?>"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><?php if(in_array($a,['admin_response','correction','reopen','cancel','block','submit'])):?><input name="body" placeholder="Details<?=in_array($a,['correction','reopen','cancel','block','submit'])?' required':''?>"><?php endif?><button><?=$a?></button></form><?php endforeach?></div><?php if(!in_array($t['workflow_status'],['completed','cancelled'])):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="post"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><select name="message_type"><option>reply</option><option>progress</option></select><input required name="body" placeholder="Message"><button>Post</button></form><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="task_action" value="upload"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input required type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt"><button>Upload proof</button></form></div><?php endif?><?php if($isAdmin):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="reassign"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><select name="assignee_id"><?php foreach($employees as $e):?><option value="<?=te($e['id'])?>"><?=te($e['name'])?></option><?php endforeach?></select><button>Reassign</button></form><?php if(in_array($t['workflow_status'],['completed','cancelled'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="task_action" value="archive"><input type="hidden" name="task_id" value="<?=$t['id']?>"><input type="hidden" name="version" value="<?=$t['version']?>"><input type="hidden" name="archive" value="<?=$t['archived_flag']?0:1?>"><button><?=$t['archived_flag']?'Unarchive':'Archive'?></button></form><?php endif?></div><?php endif?></article><?php endforeach?></section><?php if(!$isAdmin):?><section class="panel"><h2>My Reminders</h2><p>Personal reminders remain separate and never affect official performance counts.</p></section><?php endif?></main></body></html>
